DECLARE @TB_NAME AS VARCHAR(50);
DECLARE @BUTB_NAME AS VARCHAR(50);
DECLARE @BUDATE AS VARCHAR(10);

SET @TB_NAME = 'BNKM.LegalEntityAccountRole';
SET @BUDATE = CONVERT(VARCHAR(8),GETDATE(),112);
SET @BUTB_NAME = CONCAT(@TB_NAME, '_BU_',@BUDATE);

EXEC('SELECT * INTO ' + @BUTB_NAME + 'FROM '+ @TB_NAME);

SELECT PeriodEndTimestamp, COUNT(1) UPDATED FROM BNKM.LegalEntityAccountRole
WHERE PeriodEndTimestamp = '9999-12-31'
GROUP BY PeriodEndTimestamp;
